// Monitor lifecycle status. active is checking and quiet, firing has an open alert, and
// no_data found no timeseries at all. warming_up is different: the check returned series
// but the detector has too little fitted history to judge them, so the monitor keeps
// checking until it can. paused and disabled stop the checks — a person pauses, an error
// disables.
type MonitorStatus string

const (
	// The monitor is checking, and quiet.
	MonitorStatusActive MonitorStatus = "active"

	// A person paused the monitor, and no check runs.
	MonitorStatusPaused MonitorStatus = "paused"

	// The monitor has an open alert.
	MonitorStatusFiring MonitorStatus = "firing"

	// The monitor's query returned no timeseries at all.
	MonitorStatusNoData MonitorStatus = "no_data"

	// The monitor returned timeseries this check but could evaluate none of them, because its
	// detector lacks enough fitted history - an anomaly monitor still accruing its training
	// window, or one whose series stay too short or too gappy to fit. It differs from no_data
	// - there is data here, just not enough history to reach a verdict.
	MonitorStatusWarmingUp MonitorStatus = "warming_up"

	// The monitor is switched off.
	MonitorStatusDisabled MonitorStatus = "disabled"
)

// MonitorStatusValues returns every MonitorStatus the contract states, in the order it
// states them.
func MonitorStatusValues() []MonitorStatus {
	return []MonitorStatus{
		MonitorStatusActive,
		MonitorStatusPaused,
		MonitorStatusFiring,
		MonitorStatusNoData,
		MonitorStatusWarmingUp,
		MonitorStatusDisabled,
	}
}

// The decision a monitor makes. threshold fires outside a fixed range you state, anomaly on
// a departure from a model fitted on history, outlier on a series that departs from its
// peers, forecast on a crossing projected within the horizon; error fires on matching log
// records and slo on a burn-rate rule.
type MonitorType string

const (
	// Fires when the metric leaves a fixed range the user typed.
	MonitorTypeThreshold MonitorType = "threshold"

	// Scores points against a model fitted on the monitor's training period.
	MonitorTypeAnomaly MonitorType = "anomaly"

	// Judges each series against the cross-section of its peers in the same group, so it needs
	// a grouped query.
	MonitorTypeOutlier MonitorType = "outlier"

	// Projects the metric forward and fires on a crossing expected within its horizon - a
	// capacity alert.
	MonitorTypeForecast MonitorType = "forecast"

	// Fires on the log records a tracing query selects. It is the one kind that is not a
	// decision over a timeseries - there is no range to leave, and nothing is fitted.
	MonitorTypeError MonitorType = "error"

	// Evaluates burn-rate rules over an SLO's error budget.
	MonitorTypeSLO MonitorType = "slo"
)

// MonitorTypeValues returns every MonitorType the contract states, in the order it states
// them.
func MonitorTypeValues() []MonitorType {
	return []MonitorType{
		MonitorTypeThreshold,
		MonitorTypeAnomaly,
		MonitorTypeOutlier,
		MonitorTypeForecast,
		MonitorTypeError,
		MonitorTypeSLO,
	}
}

